delete from public.exhibitors where id not in ('aditora-aleph', 'amazon', 'autentica', 'autores-independentes-do-brasil', 'avec-editora', 'cabana-vermelha', 'citadel-e-altabooks', 'companhia-das-letras', 'drummond-livraria', 'editora-buzz', 'editora-caliope', 'editora-globo', 'editora-planeta', 'editora-rocco', 'editora-sunbee', 'euphoria', 'faro-editorial', 'flyve', 'grupo-editorial-record', 'harper-collins', 'intrinseca', 'new-pop', 'novo-seculo', 'qualis', 'sextante-e-arqueiro', 'skeelo', 'uiclap', 'universo-dos-livros', 'vr-editora-plataforma-21-amore-latitude');

on conflict (id) do update set
  logo = excluded.logo, name = excluded.name, description = excluded.description,
  reason_to_visit = excluded.reason_to_visit, stand_code = excluded.stand_code, active = excluded.active,
  relevance_level = excluded.relevance_level, relevance_reasons = excluded.relevance_reasons,
  categories = excluded.categories, featured = excluded.featured, updated_at = now();
